+
+// The review-side evidence slice: what a refresh updates (latest pointer
+// wins). Lifecycle fields stay core-owned.
+var DEBT_REFRESH_KEYS = ['file', 'claim', 'severityClass', 'tier', 'threadUrl',
+    'originThread', 'originPr', 'note'];
+
+// ── identity ─────────────────────────────────────────────────────────────────
